(function(){'use strict';
const KEY='albion-interface-v1';let s;try{s=JSON.parse(localStorage.getItem(KEY))}catch{}s={density:'comfortable',hints:true,sticky:true,...s};
const menu=document.createElement('details');menu.className='interface-menu';menu.innerHTML='<summary class="button" aria-label="Настройки интерфейса">⚙ Интерфейс</summary><div class="interface-options"><h3>Настройки интерфейса</h3><label>Плотность отображения<select id="view-density"><option value="comfortable">Обычная</option><option value="compact">Компактная</option></select></label><label class="refining-check"><input id="view-hints" type="checkbox"> Показывать пояснения к шагам</label><label class="refining-check"><input id="view-sticky" type="checkbox"> Закреплять результат при прокрутке</label><p>Сохраняются для всех разделов в этом браузере.</p><button id="view-reset" class="button" type="button">Вернуть обычный вид</button></div>';
document.querySelector('.header-actions').prepend(menu);const theme=document.getElementById('theme').closest('label');theme.classList.remove('server-label');menu.querySelector('.interface-options h3').after(theme);
function apply(){document.body.dataset.density=s.density==='compact'?'compact':'comfortable';document.body.dataset.explanations=s.hints?'show':'hide';document.body.dataset.sticky=s.sticky?'on':'off';document.getElementById('view-density').value=s.density;document.getElementById('view-hints').checked=s.hints;document.getElementById('view-sticky').checked=s.sticky;try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}}
document.getElementById('view-density').onchange=e=>{s.density=e.target.value;apply()};document.getElementById('view-hints').onchange=e=>{s.hints=e.target.checked;apply()};document.getElementById('view-sticky').onchange=e=>{s.sticky=e.target.checked;apply()};document.getElementById('view-reset').onclick=()=>{s={density:'comfortable',hints:true,sticky:true};apply()};
document.addEventListener('click',e=>{if(menu.open&&!menu.contains(e.target))menu.open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary').focus()}});apply();
})();
